@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalPowerConsumption : float
}

class Inhabitant {
  + username : string
  + password : string
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
  + checkThresholds() : boolean
  + sendAlert() : void
}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Inhabitant "*" -- "1" SensorController : queries
Inhabitant "0..1" -- "1" SensorController : admin
Sensor "1" *-- "1" MeasuredValue : lastValue
Sensor "1" *-- "0..*" MeasuredValue : history
Sensor "1" -- "1" Room : assignedTo
SensorController "1" -- "1" EMonitor : attachedTo
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

